cd /tmp/hwpx_verify && python3 -c "
import os
import re

for root, dirs, files in os.walk('.'):
    for f in files:
        filepath = os.path.join(root, f)
        try:
            with open(filepath, 'r', encoding='utf-8') as file:
                content = file.read()
                if '세)' in content:
                    matches = re.findall(r'[^<]*\(<\d+>세\)[^<]*', content)
                    for m in matches:
                        print(f'Age note found in {filepath}: {m}')
        except:
            pass
""}

